// --- LISTA DE PALABRAS A IGNORAR ---
// Esta lista se usa para eliminar palabras comunes antes de la comparación.
const stopWords = [
  'ads', 'ad', 'ADS', '(ADS)'
  // Puedes añadir más palabras aquí si es necesario
  // 'solar', 'llc', 'inc', 'corp', 'by', 'pr', 'de', 'la', 'los'
];

// --- LÓGICA DEL NODO ---

// Función para "limpiar" y "normalizar" un nombre de forma agresiva
function cleanAndNormalize(name) {
  if (!name) return '';

  let normalized = name.toLowerCase();

  // 1. Eliminar las "stop words" como palabras completas.
  // Esto evita que "solar" en "solaris" sea eliminado.
  stopWords.forEach(word => {
    // Se crea un RegExp para cada palabra para asegurar que se reemplace como palabra completa
    const regex = new RegExp(`\\b${word}\\b`, 'g');
    normalized = normalized.replace(regex, '');
  });

  // 2. Eliminar TODOS los caracteres que no sean letras o números.
  // Esto incluye espacios, puntos, guiones, etc., para compactar el nombre.
  // Ejemplo: "doctor ramirez" -> "doctorramirez"
  return normalized.replace(/[^\w]/gi, '');
}

// El nodo recibe un único item con los dos arrays.
const inputData = $input.first().json;

// Se accede a los arrays usando las claves del JSON de entrada.
const adAccounts = inputData.cuentas;
const crmClients = inputData.clientes;

// Validación final
if (!adAccounts || !crmClients) {
  return [{ json: { error: "Los arrays 'cuentas' o 'clientes' no se encontraron en el item de entrada." } }];
}

// Creamos un Set con los nombres limpios del CRM para una búsqueda súper rápida.
const normalizedCrmNames = new Set(
  crmClients.map(item => {
    // Ruta para el nombre del cliente del CRM
    const clientName = item.data.column_values[0].text;
    return cleanAndNormalize(clientName);
  })
);

// Filtramos la lista de cuentas de Facebook
const matchedAccounts = adAccounts.filter(adAccount => {
  // Ruta para el nombre de la cuenta publicitaria
  const adAccountName = adAccount.data.name;
  const normalizedAdName = cleanAndNormalize(adAccountName);

  // Se verifica si el nombre compactado de la cuenta existe en el Set de nombres compactados del CRM.
  return normalizedCrmNames.has(normalizedAdName);
});

// Devolvemos solo las cuentas que hicieron match.
// La estructura de cada item se mantiene intacta.
return matchedAccounts;

